export function FooterElement({
  text = "{{text}}",
  scope = "{{scope}}",
  accent = "{{accent}}",
  showLinks = {{showLinks}},
}) {
  return (
    <div style={{ width: 340, boxSizing: "border-box", font: "13px/1.5 system-ui, sans-serif" }}>
      <p style={{ margin: "0 0 8px", fontSize: 12, color: "#241430888" }}>Scope: <strong>{`<${scope}>`}</strong> footer</p>
      <footer style={{ background: "#FAF7F2", borderTop: `3px solid ${accent}`, padding: "16px 18px", borderRadius: scope === "article" ? 10 : "0 0 10px 10px" }}>
        {showLinks && (
          <nav style={{ display: "flex", gap: 14, marginBottom: 10 }}>
            <a href="#" style={{ color: accent, fontWeight: 600, fontSize: 13, textDecoration: "none" }}>Privacy</a>
            <a href="#" style={{ color: accent, fontWeight: 600, fontSize: 13, textDecoration: "none" }}>Terms</a>
            <a href="#" style={{ color: accent, fontWeight: 600, fontSize: 13, textDecoration: "none" }}>Contact</a>
          </nav>
        )}
        <p style={{ margin: 0, color: "#241430aa", fontSize: 12 }}>{text}</p>
      </footer>
    </div>
  );
}
